/**
 * MemoryCreateRequest
 * Request body for the create command.
 */
export type MemoryCreateRequest = {
    /**
     * Path
     * Path to create
     */
    path: string;
    /**
     * Content
     * Initial file content
     */
    content: string;
    /**
     * Name
     * Entry name; defaults to path's basename
     */
    name?: string | null;
    /**
     * Description
     * Optional entry description
     */
    description?: string | null;
    /**
     * Metadata
     * Optional arbitrary metadata
     */
    metadata?: {
        [key: string]: unknown;
    } | null;
};

/**
 * MemoryDeleteRequest
 * Request body for the delete command.
 */
export type MemoryDeleteRequest = {
    /**
     * Path
     * Path to delete; deletes everything under it if it's a directory
     */
    path: string;
};

/**
 * MemoryDeleteResponse
 * Response for the delete command.
 */
export type MemoryDeleteResponse = {
    /**
     * Path
     * Normalized path that was deleted
     */
    path: string;
    /**
     * Deleted Count
     * Number of entries removed
     */
    deleted_count: number;
};

/**
 * MemoryEntryResponse
 * Response for create / str_replace / insert — the entry's state after the write.
 */
export type MemoryEntryResponse = {
    /**
     * Path
     * Normalized path of the entry
     */
    path: string;
    /**
     * Name
     * Entry name
     */
    name: string;
    /**
     * Description
     * Entry description
     */
    description?: string | null;
    /**
     * Metadata
     * Arbitrary caller-supplied metadata
     */
    metadata?: {
        [key: string]: unknown;
    } | null;
    /**
     * Content
     * Full content after the write
     */
    content: string;
    /**
     * Size
     * Byte length of content
     */
    size: number;
    /**
     * Created At
     * Creation timestamp
     */
    created_at: string;
    /**
     * Updated At
     * Last update timestamp
     */
    updated_at: string;
};

/**
 * MemoryEntrySummary
 * One row in a directory listing.
 */
export type MemoryEntrySummary = {
    /**
     * Path
     * Path relative to the workspace memory root
     */
    path: string;
    /**
     * Size
     * Byte length of content for a file entry. Null for a directory entry (a path prefix with no entry stored at it directly).
     */
    size?: number | null;
};

/**
 * MemoryInsertRequest
 * Request body for the insert command.
 */
export type MemoryInsertRequest = {
    /**
     * Path
     * Path of the file to edit
     */
    path: string;
    /**
     * Insert Line
     * Line number to insert after (0-indexed at the start of the line count; 0 = beginning of file)
     */
    insert_line: number;
    /**
     * Text
     * Text to insert as a new line
     */
    text: string;
};

/**
 * MemoryRenameRequest
 * Request body for the rename command.
 */
export type MemoryRenameRequest = {
    /**
     * Old Path
     * Existing path (file or directory prefix)
     */
    old_path: string;
    /**
     * New Path
     * Destination path; must not already exist
     */
    new_path: string;
};

/**
 * MemoryRenameResponse
 * Response for the rename command.
 */
export type MemoryRenameResponse = {
    /**
     * Old Path
     * Normalized source path
     */
    old_path: string;
    /**
     * New Path
     * Normalized destination path
     */
    new_path: string;
    /**
     * Renamed Count
     * Number of entries moved
     */
    renamed_count: number;
};

/**
 * MemoryStrReplaceRequest
 * Request body for the str_replace command.
 */
export type MemoryStrReplaceRequest = {
    /**
     * Path
     * Path of the file to edit
     */
    path: string;
    /**
     * Old Str
     * Exact substring to find; must occur exactly once
     */
    old_str: string;
    /**
     * New Str
     * Replacement text
     */
    new_str: string;
};

/**
 * MemoryViewResponse
 * Response for the view command.
 *
 * Exactly one of ``content`` / ``entries`` is set, selected by
 * ``is_directory``.
 */
export type MemoryViewResponse = {
    /**
     * Path
     * Normalized path that was viewed (empty string = root)
     */
    path: string;
    /**
     * Is Directory
     * True if this is a directory listing, not a file
     */
    is_directory: boolean;
    /**
     * Content
     * Raw file content, when not a directory
     */
    content?: string | null;
    /**
     * Entries
     * Directory listing (2 levels deep), when is_directory is True
     */
    entries?: Array<MemoryEntrySummary> | null;
};

/**
 * MessageResponse
 * Generic message response.
 */
export type MessageResponse = {
    /**
     * Message
     */
    message: string;
};

/**
 * NotifySettings
 * Who to @-mention when Jeanclode is done with a PR/MR it opened.
 *
 * Provider identity ids, not handles: a GitLab/GitHub rename would
 * otherwise leave a stale username here and silently stop notifying.
 * Resolved to handles at dispatch time (``add_notify_to_inputs``).
 */
export type NotifySettings = {
    /**
     * On Ready
     * Provider identity IDs to mention once a bot-opened PR/MR is ready
     */
    on_ready?: Array<string>;
};

